// Helper to find previous and next posts
export function getAdjacentBlogPosts(currentSlug: string): {
  prevPost: BlogPostNav | null;
  nextPost: BlogPostNav | null;
  currentPost: BlogPostNav | null;
} {
  // Normalize slug (strip leading/trailing slashes)
  const cleanSlug = currentSlug.replace(/^\/+|\/+$/g, '');
  
  // Handle bonus/ad-hoc blogs gracefully if visited directly
  if (cleanSlug === 'blog-webhooks') {
    const prevPost = BLOG_POSTS.find(p => p.slug === 'blog-wordpress') || null;
    const nextPost = BLOG_POSTS.find(p => p.slug === 'blog-google-cloud-summit') || null;
    return {
      currentPost: {
        number: '32b',
        slug: 'blog-webhooks',
        titles: {
          es: 'Querido Diario, Qué Es un Webhook y Por Qué No Todas las APIs Funcionan Igual 🌸',
          en: 'Dear Diary, What Is a Webhook & How Do They Differ From Regular APIs? 🌸',
          pt: 'Querido Diário, O Que É um Webhook e Por Que Nem Todas as APIs Funcionam Igual 🌸'
        },
        shortTitles: {
          es: 'Webhooks vs APIs',
          en: 'Webhooks vs APIs',
          pt: 'Webhooks vs APIs'
        }
      },
      prevPost,
      nextPost
    };
  }

  if (cleanSlug === 'blog-scraping') {
    const prevPost = BLOG_POSTS.find(p => p.slug === 'blog-vertex-ai') || null;
    const nextPost = BLOG_POSTS.find(p => p.slug === 'blog-vector-search') || null;
    return {
      currentPost: {
        number: '35b',
        slug: 'blog-scraping',
        titles: {
          es: 'Querido Diario, Qué Es Web Scraping y Cómo lo Usé para Descodificar Animaciones de GSAP 🌸',
          en: 'Dear Diary, What Is Web Scraping & How I Used It to Reverse-Engineer GSAP Animations 🌸',
          pt: 'Querido Diário, O Que É Web Scraping & Como Usei para Decodificar Animações em GSAP 🌸'
        },
        shortTitles: {
          es: 'Web Scraping & GSAP',
          en: 'Web Scraping & GSAP',
          pt: 'Web Scraping & GSAP'
        }
      },
      prevPost,
      nextPost
    };
  }

  const index = BLOG_POSTS.findIndex(p => p.slug === cleanSlug);
  if (index === -1) {
    return { prevPost: null, nextPost: null, currentPost: null };
  }

  const currentPost = BLOG_POSTS[index];
  const prevPost = index > 0 ? BLOG_POSTS[index - 1] : null;
  const nextPost = index < BLOG_POSTS.length - 1 ? BLOG_POSTS[index + 1] : null;

  return { prevPost, nextPost, currentPost };
}
